const manuscript = $("Fetch Manuscript").first().json;
const chapters = $("Fetch Chapters")
  .all()
  .map((item) => item.json);

console.log("Processing manuscript:", manuscript.title);
console.log("Total chapters:", chapters.length);

// Calculate actual total word count from all chapters
const fullText = chapters
  .map((c) => c.content)
  .filter((c) => c)
  .join("\n\n");
const actualWordCount = fullText
  .split(/\s+/)
  .filter((w) => w.length > 0).length;

// Build structure for analysis nodes
const manuscriptData = {
  manuscriptId: manuscript.id,
  authorName:
    `${manuscript.author_first_name || ""} ${manuscript.author_last_name || ""}`.trim() ||
    "Author",
  manuscriptTitle: manuscript.title,
  genre: manuscript.genre || "Fiction",
  totalWordCount: actualWordCount,
  totalChapters: chapters.length,

  // Full text for analysis
  fullText: fullText,

  // Structured chapters with all data
  chapters: chapters.map((ch, index) => ({
    chapterId: ch.id,
    chapterNumber: ch.chapter_number,
    title: ch.title || `Chapter ${ch.chapter_number}`,
    content: ch.content,
    wordCount: ch.content
      ? ch.content.split(/\s+/).filter((w) => w.length > 0).length
      : 0,
    previousChapterTitle: index > 0 ? chapters[index - 1].title : null,
    nextChapterTitle:
      index < chapters.length - 1 ? chapters[index + 1].title : null,
    progressPercent: Math.round(((index + 1) / chapters.length) * 100),
  })),

  // Story context for AI nodes
  storyContext: {
    totalChapters: chapters.length,
    genre: manuscript.genre || "Unknown",
    totalWordCount: actualWordCount,
  },

  // Metadata
  analysisDate: new Date().toLocaleDateString("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
  }),
};

console.log(
  "Processed data:",
  JSON.stringify(
    {
      title: manuscriptData.manuscriptTitle,
      author: manuscriptData.authorName, // ✅ LOG IT
      totalChapters: manuscriptData.totalChapters,
      totalWordCount: manuscriptData.totalWordCount,
      genre: manuscriptData.genre,
    },
    null,
    2,
  ),
);

return { json: manuscriptData };

// Extract manuscript ID from the storage Key
const key = $json.Key; // e.g., "manuscript-reports/77977e52-85d9-4a38-9abc-3bbadc0768c7_report.pdf"

console.log('=== EXTRACTING DATA FROM STORAGE KEY ===');
console.log('Key:', key);

// Extract the UUID from the filename (between / and _report.pdf or _alex_report.pdf)
const match = key.match(/manuscript-reports\/([a-f0-9-]+)_/);
const manuscriptId = match ? match[1] : null;

if (!manuscriptId) {
  throw new Error(`Could not extract manuscript ID from key: ${key}`);
}

console.log('✅ Extracted manuscript ID:', manuscriptId);

// Construct the full public URL
const publicUrl = `https://itlkncjiifbgvmvuejgm.supabase.co/storage/v1/object/public/${key}`;

console.log('✅ Public URL:', publicUrl);

// Return data that BOTH branches can use
return {
  json: {
    manuscriptId: manuscriptId,
    reportUrl: publicUrl,
    storageKey: key,
    storageId: $json.Id
  }
};

return {
  json: {
    success: true,
    message: "PDF report generated and emailed",
    manuscriptId: $('Webhook').first().json.body.manuscriptId,
    reportComplete: true,
    timestamp: new Date().toISOString()
  }
};

// SIMPLE REPORT FORMATTING FOR FULL ANALYSIS
const synthesisResult = $("Final Synthesis").first().json; // ← Changed to reference Final Synthesis directly

console.log("=== FORMATTING FULL ANALYSIS REPORT ===");
console.log("Synthesis result keys:", Object.keys(synthesisResult));

// Get manuscript metadata from earlier in the flow
const manuscriptData = $("Fetch Manuscript").first().json;

console.log("Manuscript data keys:", Object.keys(manuscriptData));

// Get the AI-generated report - check multiple possible field names
const analysisReport =
  synthesisResult.output ||
  synthesisResult.text ||
  synthesisResult.response ||
  "";

console.log("Analysis report found:", !!analysisReport);
console.log("Analysis report length:", analysisReport?.length || 0);

if (!analysisReport || analysisReport.length < 100) {
  console.error(
    "Available keys in synthesisResult:",
    Object.keys(synthesisResult),
  );
  throw new Error("No analysis content found");
}

console.log("✅ Analysis report length:", analysisReport.length);

// Convert markdown to HTML
let htmlAnalysis = analysisReport
  .replace(
    /^# (.+)$/gm,
    '<h1 style="color: #2c3e50; font-size: 1.8rem; margin: 25px 0 15px 0; border-bottom: 2px solid #27ae60; padding-bottom: 10px;">$1</h1>',
  )
  .replace(
    /^## (.+)$/gm,
    '<h2 style="color: #34495e; font-size: 1.4rem; margin: 20px 0 12px 0; border-left: 4px solid #27ae60; padding-left: 15px;">$1</h2>',
  )
  .replace(
    /^### (.+)$/gm,
    '<h3 style="color: #5d6d7e; font-size: 1.2rem; margin: 18px 0 10px 0;">$1</h3>',
  )
  .replace(/\*\*(.*?)\*\*/g, '<strong style="font-weight: 600;">$1</strong>')
  .replace(/\*(.*?)\*/g, "<em>$1</em>")
  .replace(/\n\n/g, '</p><p style="margin: 15px 0; line-height: 1.6;">')
  .replace(/^/, '<p style="margin: 15px 0; line-height: 1.6;">')
  .replace(/$/, "</p>");

const currentDate = new Date().toLocaleDateString("en-US", {
  year: "numeric",
  month: "long",
  day: "numeric",
});

// Get author name from manuscript data (not from Fetch Author Email)
const authorName = `${manuscriptData.author_first_name || ""} ${manuscriptData.author_last_name || ""}`.trim() || "Author";

console.log("✅ Using author name:", authorName);

// Create complete report data
const reportData = {
  authorName: authorName,
  manuscriptTitle: manuscriptData.manuscriptTitle || manuscriptData.title,
  analysisDate: currentDate,
  totalWordCount: (
    manuscriptData.totalWordCount ||
    manuscriptData.wordCount ||
    0
  ).toLocaleString(),
  totalChapters:
    manuscriptData.totalChapters || manuscriptData.chapterCount || 0,
  genre: manuscriptData.genre || "Fiction",
  analysisReport: htmlAnalysis,
  manuscriptId:
    manuscriptData.id || $("Webhook").first().json.body.manuscriptId,
};

console.log("✅ Report formatted successfully");
console.log("- Author:", reportData.authorName);
console.log("- Title:", reportData.manuscriptTitle);
console.log("- Word Count:", reportData.totalWordCount);

return { json: reportData };

const pdfData = $('PDF Generator').first();
const emailData = $('Fetch Author Email').first().json;
const manuscriptData = $('Manuscript Processing').first().json;

console.log('=== COMBINING PDF AND EMAIL DATA ===');
console.log('PDF Filename Setup keys:', Object.keys(pdfData));
console.log('PDF binary exists:', !!pdfData.binary);
console.log('PDF binary.data exists:', !!pdfData.binary?.data);
console.log('Email data:', emailData);

// Verify binary data exists
if (!pdfData.binary || !pdfData.binary.data) {
  throw new Error('PDF binary data not found. Check PDF Generator → PDF Filename Setup connection.');
}

console.log('✅ Binary data found, fileName:', pdfData.binary.data.fileName);

// Create combined output with both binary and email fields
const combined = {
  json: {
    email: emailData.email,
    firstName: emailData.first_name,
    lastName: emailData.last_name,
    manuscriptTitle: emailData.manuscript_title || manuscriptData.manuscriptTitle,
    authorName: `${emailData.first_name} ${emailData.last_name}`,
    manuscriptId: manuscriptData.manuscriptId || manuscriptData.id
  },
  binary: {
    data: pdfData.binary.data // PDF binary with updated filename
  }
};

console.log('✅ Combined data created successfully');
console.log('Email will be sent to:', combined.json.email);
console.log('PDF filename:', combined.binary.data.fileName);

return combined;

